    let mut r: i32 = 0;
    let mut row: i32 = 0;
    let mut prod: i32 = 0;
    let mut page: i32 = 0;
    let mut bx0: i32 = 0;
    let mut by0: i32 = 0;
    let mut bx1: i32 = 0;
    let mut by1: i32 = 0;
    let mut vx0: i32 = 0;
    let mut vy0: i32 = 0;
    let mut vx1: i32 = 0;
    let mut vy1: i32 = 0;
    let mut clip: i32 = -1;
    let mut flags: i32 = 0;
    let mut ori: i32 = 0;
    let mut obj: i32 = 0;
    let mut pw: i32 = 0;
    let mut ph: i32 = 0;
    let mut f: i32 = 0;
    let mut rc: i32 = 0;
    let mut zz: i32 = 0;
    let mut work: i32 = 0;
    let mut ovl: i32 = AS_OVERLAY_WORK;
    let mut whole: i32 = 0;
