            bx0 = im_get(im, r, mf_x0());
            by0 = im_get(im, r, mf_y0());
            bx1 = im_get(im, r, mf_x1());
            by1 = im_get(im, r, mf_y1());
            vx0 = bx0;
            vy0 = by0;
            vx1 = bx1;
            vy1 = by1;
            flags = 0;
